def main():
    conn = psycopg2.connect(DB_URL)
    cur  = conn.cursor(cursor_factory=psycopg2.extras.DictCursor)

    updated = created = skipped = 0
    now = datetime.utcnow()

    for style_number, colors in IMAGE_DATA.items():
        cur.execute("SELECT id FROM product WHERE style_number = %s", (style_number,))
        row = cur.fetchone()
        if not row:
            print(f"  [SKIP] {style_number} — not in DB")
            skipped += len(colors)
            continue
        product_id = row[0]

        first_front = first_back = None

        for color_name, sides in colors.items():
            front_url = sides.get("front","")
            back_url  = sides.get("back","")
            if not front_url and not back_url:
                skipped += 1
                continue

            cur.execute(
                "SELECT id FROM product_color_variant WHERE product_id=%s AND lower(color_name)=lower(%s)",
                (product_id, color_name)
            )
            existing = cur.fetchone()
            if existing:
                cur.execute(
                    "UPDATE product_color_variant SET front_image_url=%s, back_image_url=%s, last_synced=%s WHERE id=%s",
                    (front_url or None, back_url or None, now, existing[0])
                )
                updated += 1
            else:
                cur.execute(
                    "INSERT INTO product_color_variant (product_id, color_name, front_image_url, back_image_url, last_synced) VALUES (%s,%s,%s,%s,%s)",
                    (product_id, color_name, front_url or None, back_url or None, now)
                )
                created += 1

            if not first_front and front_url: first_front = front_url
            if not first_back  and back_url:  first_back  = back_url

        # Set product-level mockup template if blank
        if first_front:
            cur.execute(
                "UPDATE product SET front_mockup_template=%s WHERE id=%s AND (front_mockup_template IS NULL OR front_mockup_template='')",
                (first_front, product_id)
            )
        if first_back:
            cur.execute(
                "UPDATE product SET back_mockup_template=%s WHERE id=%s AND (back_mockup_template IS NULL OR back_mockup_template='')",
                (first_back, product_id)
            )

    conn.commit()
    cur.close()
    conn.close()
    print(f"Done! Updated: {updated} | Created: {created} | Skipped: {skipped}")

if __name__ == "__main__":
    main()
